function verif1(f){
if(f.idUtil.value==""){
    alert("ID vide");
    return false;}
if(f.nomPrenom.value==""){
    alert("Nom vide");
    return false;}
return true;
}

function verif2(f){
if(f.nomDoc.value==""){
    alert("Choisir document");
    return false;}
if(f.idUtil.value==""){
    alert("ID vide");
    return false;}
if(!f.ecriture.checked&&!f.lecture.checked&&!f.impression.checked){
    alert("Choisir un droit");
    return false;}
return true;
}

function choix1(c,f){
    if(c.checked)
        f.lecture.checked=true;}
function choix2(c,f){
    if(!c.checked){
        f.ecriture.checked=false;
        f.impression.checked=false;}}
function choix3(c,f){
    if(c.checked)f.lecture.checked=true;}
function annuler(f){
    f.reset();
    return false;}

